import csv
import json
from copy import deepcopy


class Parameters(dict):
    def __init__(self, path=None, delimiter=","):
        dict.__init__(self)
        self.__lines = []
        self.__data = self.__read(path, delimiter)
        self.__path = path
        self.__delimiter = delimiter
        self.parse()

    @property
    def delimiter(self):
        return self.__delimiter

    @property
    def path(self):
        return self.__path

    @staticmethod
    def __full_lines(path, delimiter):
        with open(path, "r") as file:
            csv_lines = list(csv.reader(file, delimiter=delimiter))
        full_lines = []
        for csv_line in csv_lines:
            if len(csv_line) == 0:
                continue
            full_lines.append(csv_line)

        for i in range(len(full_lines)):
            if i == 0:
                continue
            for j in range(len(full_lines[i])):
                if full_lines[i][j] != "":
                    break
                try:
                    full_lines[i][j] = full_lines[i - 1][j]
                except IndexError:
                    continue
        return full_lines

    def __read(self, path, delimiter):
        if path is None:
            return []
        lines = self.__full_lines(path, delimiter)
        self.__lines = deepcopy(lines)

        for i in range(len(lines)):
            new_lines = []
            for j in range(len(lines[i])):
                if lines[i][j] != "":
                    new_lines.append(lines[i][j])
                    continue
                if j == len(lines[i]) - 1:
                    new_lines.append(lines[i][j])
            lines[i] = new_lines

        return lines

    def write(self):
        """
        Write the csv.
        """
        # step1: Convert map to list
        results = dict_to_list(self)
        value_map = {}
        for result in results:
            value_map["$".join(result[:-1])] = result[-1]

        # step2: Replace the old value to new value
        for i in range(len(self.__lines)):
            key = ("$".join(self.__lines[i][:-1])).strip("$")
            if key not in value_map:
                print("key %s not in value_map." % key)
                continue
            self.__lines[i][-1] = value_map[key]
            del value_map[key]

        self.__merge_lines(map_to_full_list(value_map, len(self.__lines[0])))

        # step3: Restore default indent format
        for i in range(len(self.__lines)-1, 0, -1):
            for j in range(len(self.__lines[i][:-1])):
                if self.__lines[i][j] != self.__lines[i-1][j]:
                    break
                self.__lines[i][j] = ""

        # step4: Write the list to the csv file
        with open(self.path, "w") as file:
            csv.writer(file).writerows(self.__lines)

    def __merge_lines(self, new_lines):
        if len(new_lines) == 0:
            return

        for new_line in new_lines:
            position = 0
            max_repeat = 0
            for i in range(len(self.__lines)):
                loop_repeat = 0
                for j in range(len(self.__lines[i])):
                    if self.__lines[i][j] == new_line[j]:
                        loop_repeat += 1
                        continue

                    if loop_repeat >= max_repeat:
                        max_repeat = loop_repeat
                        position = i
            self.__lines.insert(position, new_line)

    def parse(self):
        for row in self.__data:
            if len(row) == 2:
                self[row[0]] = row[1]
                continue
            item = self.__create_item(row)
            self.extend(item)

    def extend(self, item):
        extend_dict(self, item)

    @staticmethod
    def __create_item(row):
        item = {row[-2]: row[-1]}
        row = row[:-2]
        while len(row) > 0:
            key = row.pop()
            item = {key: item}
        return item

    def json(self, indent=4):
        """
        Convert the parameters to JSON string. The default indent value is 4.
        If the indent value is less than 0, the method defaults to 0.
        """
        indent = 0 if indent < 0 else indent
        return json.dumps(self, indent=indent)


def extend_dict(old, new):
    if (not isinstance(old, dict)) or (not isinstance(new, dict)):
        return

    for key in new:
        if key not in old:
            old[key] = new[key]
            return
        extend_dict(old[key], new[key])


def dict_to_list(data):
    result = []
    for key in data:
        if isinstance(data[key], dict):
            item = dict_to_list(data[key])
            for i in item:
                i.insert(0, key)
                result.append(i)
        else:
            result.append([key, data[key]])
    return result


def map_to_full_list(data, original_length):
    result = []
    for key in data:
        item_list = key.split("$")
        if len(item_list) < (original_length - 1):
            for i in range(original_length - 1 - len(item_list)):
                item_list.append("")
        item_list.append(data[key])
        result.append(item_list)
    return result
